 VALUES('Démonstration Lehnova','Boucherie des Halles','boucherie-des-halles','#872E29','elegante','https://images.pexels.com/photos/5313882/pexels-photo-5313882.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1200&h=800',true,'Le goût des bons moments','Bienvenue chez votre artisan boucher : découvrez nos pièces à griller, nos volailles et nos préparations pour tous les jours. Catalogue de démonstration Lehnova : commerce, tarifs et offres fictifs.') RETURNING id INTO catalog_id;
 VALUES('Boucherie des Halles · Démo','boucherie-des-halles',true,'https://lehnova.fr/catalogue/boucherie-des-halles#promotions-du-moment','[{"title":"Duo de steaks à griller","detail":"19,90 € le lot","image_url":"https://images.pexels.com/photos/5313882/pexels-photo-5313882.jpeg?auto=compress&cs=tinysrgb&w=900","url":null},{"title":"Filets de poulet marinés","detail":"12,90 € / kg","image_url":"https://images.pexels.com/photos/6107755/pexels-photo-6107755.jpeg?auto=compress&cs=tinysrgb&w=900","url":null},{"title":"Pièce de bœuf du week-end","detail":"24,90 € / kg","image_url":"https://images.pexels.com/photos/20187072/pexels-photo-20187072.jpeg?auto=compress&cs=tinysrgb&w=900","url":null}]'::jsonb,true) RETURNING id INTO business_id;
